import{_ as o,o as a,c as s,a2 as i}from"./chunks/framework.CZcFxxdw.js";const u=JSON.parse('{"title":"深入理解C/C++的编译与链接技术8：库文件检索逻辑","description":"","frontmatter":{"title":"深入理解C/C++的编译与链接技术8：库文件检索逻辑","description":"","tags":["cpp-modern","host","intermediate"],"difficulty":"intermediate","platform":"host","chapter":13,"order":8},"headers":[],"relativePath":"compilation/08-library-search-logic.md","filePath":"compilation/08-library-search-logic.md","lastUpdated":null}'),d={name:"compilation/08-library-search-logic.md"};function t(l,e,c,n,r,p){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="深入理解c-c-的编译与链接技术8-库文件检索逻辑" tabindex="-1">深入理解C/C++的编译与链接技术8：库文件检索逻辑 <a class="header-anchor" href="#深入理解c-c-的编译与链接技术8-库文件检索逻辑" aria-label="Permalink to &quot;深入理解C/C++的编译与链接技术8：库文件检索逻辑&quot;">​</a></h1><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><p>现在，我们需要讨论的是定位库文件的事情。定位库文件说的是——一个依赖了针对于本体而言的其他动态库文件的可执行文件，是如何找到这些其他动态库文件的？</p><p>这个问题并非小问题，仔细一想，在现代的软件工程中，我们几乎逃脱不了库文件的使用。比如说，我们制作的一些软件或者是使用的软件会将第三方的库集成到产品中使用，或者是以包管理模式为代表的，为了让一个给定的软件正确运行，我们需要在运行的时候定位正确的库文件。</p><p>几乎就是如此。</p><h2 id="定位规则" tabindex="-1">定位规则 <a class="header-anchor" href="#定位规则" aria-label="Permalink to &quot;定位规则&quot;">​</a></h2><p>Linux下的动态库是存在命名规范的，如果您注意的话，是可以发现所有的静态库都满足<code>lib + &lt;library_name&gt; + .a</code>的，这个时候，我们只需要告诉链接器<code>&lt;library_name&gt;</code>的部分，链接器会自动按照其他规则查找<code>lib&lt;library_name&gt;.a</code>的</p><p>动态库要更加复杂一丁点，因为动态库具备热替换属性（即无需从头编译软件发布），所以实际上命名规则还要复杂一点，简单的说是：</p><p><code>lib + &lt;library_name&gt; + .so + &lt;library version information&gt;</code></p><p>还是一样，我们只用提供<code>&lt;library_name&gt;</code>的部分，链接器会自动按照其他规则查找的。</p><p><code>&lt;library version information&gt;</code>值得单独谈谈，一般而言，版本号就足以：<code>&lt;M&gt;.&lt;m&gt;.&lt;p&gt;</code>，也就是主版本号，次版本号和补丁版本号。这个是具体的名称，还有一个东西叫做soname，是只留下主版本号信息的动态库名称，即：<code>libz.so.1.2.3.4</code>的soname是libz.so.1。这个是《高级C/C++编译技术》的例子。</p><h2 id="说一说运行启动时的动态库定位规则" tabindex="-1">说一说运行启动时的动态库定位规则 <a class="header-anchor" href="#说一说运行启动时的动态库定位规则" aria-label="Permalink to &quot;说一说运行启动时的动态库定位规则&quot;">​</a></h2><p>现在我们需要聊聊动态库文件的运行定位规则。特别的，大家可能关心Linux运行时的动态库定位规则。这里说一下。在 Linux 上运行动态链接程序时，一个叫<strong>动态链接器 / loader</strong>（通常是 <code>ld-linux.so</code> / <code>ld.so</code>）的组件负责找到并加载可执行文件所需的共享库（<code>.so</code>）。动态库的查找规则看起来复杂，但其实是有明确优先级和几条常见&quot;控制点&quot;：<code>LD_PRELOAD</code>、可执行文件内嵌的 <code>RPATH</code>/<code>RUNPATH</code>、环境变量 <code>LD_LIBRARY_PATH</code>、系统配置（<code>/etc/ld.so.conf.d</code> + <code>ldconfig</code>）以及系统默认路径（如 <code>/lib</code>、<code>/usr/lib</code>）。</p><p>下面的部分，是各位需要了解的：<strong>当动态链接器需要解析某个依赖</strong>（即依赖名没有包含 <code>/</code>）时，通常按以下顺序查找（已简化）：</p><ol><li><code>LD_PRELOAD</code> 指定的库（优先加载，用于符号覆盖／注入）。</li><li>如果可执行文件包含 <code>DT_RPATH</code> 并且没有 <code>DT_RUNPATH</code>，则使用 <code>DT_RPATH</code> 路径（注意：<code>DT_RPATH</code> 已被弃用，但仍被支持）。</li><li>环境变量 <code>LD_LIBRARY_PATH</code>（<strong>非 setuid/setgid 可执行文件会被忽略</strong>）。</li><li>如果可执行文件包含 <code>DT_RUNPATH</code>，使用 <code>DT_RUNPATH</code>（并且当存在 <code>DT_RUNPATH</code> 时，<code>DT_RPATH</code> 一般被忽略）。</li><li>ldconfig 维护的缓存 <code>/etc/ld.so.cache</code>，以及 <code>/lib</code>、<code>/usr/lib</code>（以及架构相关的 <code>/lib64</code>、<code>/usr/lib64</code>）这些&quot;trusted directories&quot;。</li><li>（如果前面都没找到）最终会失败并报错（如 <code>ld.so: cannot find ...</code>）。</li></ol><blockquote><p>注意：上面顺序的细节（特别是 <code>RPATH</code> 与 <code>RUNPATH</code> 的交互）由 linker 的实现与链接器选项（如 <code>--enable-new-dtags</code>，这个标识符是启用-R或者是-rpath链接器指导选项）影响。</p></blockquote><hr><h2 id="详细说明-每项展开" tabindex="-1">详细说明（每项展开） <a class="header-anchor" href="#详细说明-每项展开" aria-label="Permalink to &quot;详细说明（每项展开）&quot;">​</a></h2><h4 id="ld-preload-按需-注入-或覆盖符号" tabindex="-1">LD_PRELOAD（按需&quot;注入&quot;或覆盖符号） <a class="header-anchor" href="#ld-preload-按需-注入-或覆盖符号" aria-label="Permalink to &quot;LD_PRELOAD（按需&quot;注入&quot;或覆盖符号）&quot;">​</a></h4><p><code>LD_PRELOAD</code> 是一个环境变量，可指定一个或多个共享库，<strong>在正常搜索之前</strong>被强制加载到进程中，从而可以用于拦截/替换符号（函数）。不过这个很少见，一般是不建议使用的，除非你知道你在做什么 😃</p><hr><h4 id="dt-rpath-与-dt-runpath-即-rpath-runpath" tabindex="-1">DT_RPATH 与 DT_RUNPATH（即 &quot;rpath / runpath&quot;） <a class="header-anchor" href="#dt-rpath-与-dt-runpath-即-rpath-runpath" aria-label="Permalink to &quot;DT_RPATH 与 DT_RUNPATH（即 &quot;rpath / runpath&quot;）&quot;">​</a></h4><p>在链接时，可以把一个或多个运行时库搜索路径写进可执行文件或共享库的动态段（<code>.dynamic</code>），对应 ELF tag 分别是 <code>DT_RPATH</code> 和 <code>DT_RUNPATH</code>。历史上的 <code>DT_RPATH</code> 早期引入，用法是&quot;优先于环境变量&quot;，但后来引入了 <code>DT_RUNPATH</code>（new-dtags），<code>DT_RUNPATH</code> 的含义是：<strong>它在 <code>LD_LIBRARY_PATH</code> 之后被搜索</strong>，即 <code>LD_LIBRARY_PATH</code> 可以覆盖 RUNPATH 中的路径；而 <code>DT_RPATH</code> 在某些实现/历史上会优先于 <code>LD_LIBRARY_PATH</code>（即更难被重写）。</p><p>另一个重要行为差别：<strong>DT_RPATH 对传递依赖（transitive dependencies）有效</strong>，而 <strong>DT_RUNPATH 可能不会用于查找传递依赖</strong>（即当可执行 -&gt; libA -&gt; libB 时，RUNPATH 的行为在某些情况下不会为 libB 的查找提供路径，而 RPATH 会）。这导致某些在旧链接器下以 RPATH 可运行的组合，在使用 RUNPATH（new-dtags）后会出现&quot;找不到间接依赖&quot;的情况。</p><p>笔者目前的Linux经验中的确很少接触到，所以建议更多的测试环境下，采用下面这个方案是合适的</p><hr><h4 id="ld-library-path-这个是环境变量" tabindex="-1">LD_LIBRARY_PATH（这个是环境变量） <a class="header-anchor" href="#ld-library-path-这个是环境变量" aria-label="Permalink to &quot;LD_LIBRARY_PATH（这个是环境变量）&quot;">​</a></h4><p><code>LD_LIBRARY_PATH</code> 是运行时的库搜索路径列表，会被动态链接器在特定阶段使用（见顺序）。非常常用作临时覆盖系统路径或测试新版本库。<strong>同样的</strong>，setuid / setgid 可执行文件会忽略此变量（安全原因）。</p><p>环境变量的麻烦在于很容易干扰到所有的由设置了这个环境变量的shell不建议把生产环境长期依赖 <code>LD_LIBRARY_PATH</code>，因为它会影响所有通过该 shell 启动的子进程，并且不如系统配置（ldconfig）可维护。</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> LD_LIBRARY_PATH</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/opt/foo/lib:/home/you/sw/lib:$LD_LIBRARY_PATH</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./myapp</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><hr><h4 id="ldconfig、-etc-ld-so-conf-d、以及-ld-so-cache" tabindex="-1">ldconfig、/etc/ld.so.conf.d、以及 ld.so.cache <a class="header-anchor" href="#ldconfig、-etc-ld-so-conf-d、以及-ld-so-cache" aria-label="Permalink to &quot;ldconfig、/etc/ld.so.conf.d、以及 ld.so.cache&quot;">​</a></h4><p>系统管理员通常通过把库目录放到 <code>/etc/ld.so.conf</code> 或 <code>/etc/ld.so.conf.d/*.conf</code> 来告诉 <code>ldconfig</code> 哪些目录要被系统动态链接器信任。<code>ldconfig</code> 会扫描这些目录并生成一个二进制缓存 <code>/etc/ld.so.cache</code>（提高查找速度），同时创建符号链接（libXXX.so -&gt; libXXX.so.VERSION）。动态链接器会读取该缓存来加速查找。</p><p>常见操作：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 把新目录加入配置（以 root）</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;/opt/foo/lib&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/ld.so.conf.d/foo.conf</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 重建缓存</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ldconfig</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 查看缓存内容</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ldconfig</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> foo</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><hr><h4 id="系统默认目录-trusted-directories" tabindex="-1">系统默认目录（trusted directories） <a class="header-anchor" href="#系统默认目录-trusted-directories" aria-label="Permalink to &quot;系统默认目录（trusted directories）&quot;">​</a></h4><p>动态链接器通常会默认搜索 <code>/lib</code>、<code>/usr/lib</code>（以及在 64-bit 系统上的 <code>/lib64</code>、<code>/usr/lib64</code>），这些目录被称为&quot;trusted directories&quot;。<code>ldconfig</code> 也会处理这些目录。即使没有把一个路径写入 <code>ld.so.conf</code>，把库放在这些目录通常也能被找到（但要注意架构位、ABI、版本匹配）。</p><h2 id="那咱们windows呢" tabindex="-1">那咱们Windows呢？ <a class="header-anchor" href="#那咱们windows呢" aria-label="Permalink to &quot;那咱们Windows呢？&quot;">​</a></h2><p>Windows 的可执行/装载器与 API（<code>LoadLibrary</code> / <code>LoadLibraryEx</code> / 自动加载 via import table）定义了一套搜索顺序和安全改进。</p><p>一般而言，Windows的方式有两种：隐式（导入表）与显式（运行时 API）</p><p>**隐式加载（implicit）**指的是可执行文件的导入表（Import Table）在进程启动或模块加载时由系统装载器解析，系统会为每个 <code>DLL</code> 尝试找到并映射到进程地址空间。开发者在链接阶段指定依赖（例如 <code>kernel32.dll</code>、<code>mydll.dll</code>），加载由系统在进程启动时期自动完成。</p><p>**显式加载（explicit）**指的是代码在运行时使用 <code>LoadLibrary</code> / <code>LoadLibraryEx</code> 等 API 手工加载 DLL，然后用 <code>GetProcAddress</code> 取得函数指针。显式加载能通过参数控制搜索行为（例如使用 <code>LOAD_LIBRARY_SEARCH_USER_DIRS</code> 等标志）。</p><h4 id="默认搜索顺序-概念化顺序" tabindex="-1">默认搜索顺序（概念化顺序） <a class="header-anchor" href="#默认搜索顺序-概念化顺序" aria-label="Permalink to &quot;默认搜索顺序（概念化顺序）&quot;">​</a></h4><blockquote><p>注意：Windows 的搜索顺序在不同 OS 版本与配置下有细微差别，且系统提供了影响该顺序的设置（下文会说明）。这里先给出一个概念化的常见顺序（理解优先级即可）：</p></blockquote><p>当进程请求加载名为 <code>foo.dll</code>（未指定绝对路径）时，系统通常按以下顺序查找（概念顺序）：</p><ol><li><strong>调用方显式指定的完整路径</strong>（如果调用 <code>LoadLibrary(&quot;C:\\\\path\\\\foo.dll&quot;)</code>，则直接加载该路径，不走搜索）。</li><li><strong>加载器首先查看是否为&quot;KnownDLLs&quot;中的条目</strong>（KnownDLLs 是注册在系统中的一组受信任的系统库，优先使用系统已存在版本）。</li><li><strong>应用程序目录（Executable directory）</strong>：可执行程序（.exe）所在目录（通常优先于系统目录，具体受 SafeDllSearchMode 等设置影响）。</li><li><strong>系统目录</strong>（通常为 <code>%SystemRoot%\\System32</code>）。</li><li><strong>Windows 目录</strong>（通常为 <code>%SystemRoot%</code>）。</li><li><strong>当前工作目录（Current Directory）</strong>（取决于 SafeDllSearchMode；若启用&quot;安全搜索模式&quot;，current directory 的位置会被推后）。</li><li><strong>PATH 环境变量中列出的目录</strong>（按顺序）。</li><li><strong>如果启用了应用配置或 Side-by-side（SxS）/manifest 特性</strong>，会优先解析 manifest 中声明的绑定版本或来自 WinSxS 的并行程序集。</li></ol><p>重点是：<strong>如果你使用了绝对路径或相对可执行文件路径，系统不会去 PATH 搜索</strong>；反之如果只给了裸名 <code>foo.dll</code>，就会按上面顺序尝试。</p>`,48)])])}const b=o(d,[["render",t]]);export{u as __pageData,b as default};
